const s=t=>{const n=[],o=[];for(const h of t.split(/[,;\n]+/)){const m=h.trim();if(!m)continue;const e=m.match(/^(\d+(?:\.\d+)?)\s*(?:x|×|\*|by)\s*(\d+(?:\.\d+)?)\s*(?:µm|um|μm)?$/i),i=e?Number(e[1]):NaN,r=e?Number(e[2]):NaN;!e||r<=0||i<=0||i>500||r>500?o.push(m):n.push({length:i,width:r})}return{spores:n,invalid:o}},c=t=>{const n=t.length,o=t.reduce((m,e)=>m+e,0)/n,h=n>1?Math.sqrt(t.reduce((m,e)=>m+(e-o)**2,0)/(n-1)):0;return{min:Math.min(...t),max:Math.max(...t),mean:o,sd:h}},g=t=>t.length===0?null:{n:t.length,length:c(t.map(n=>n.length)),width:c(t.map(n=>n.width)),q:c(t.map(n=>n.length/n.width))},a=t=>t.toFixed(1),d=t=>t.toFixed(2),l=t=>`${a(t.length.min)}–${a(t.length.max)} × ${a(t.width.min)}–${a(t.width.max)} µm, mean ${a(t.length.mean)} × ${a(t.width.mean)} µm, Q = ${d(t.q.min)}–${d(t.q.max)}, Qm = ${d(t.q.mean)}, n = ${t.n}`;export{l as f,s as p,g as s};
